const trigger = $input.first().json || {};
let account_id = trigger.account_id ? parseInt(trigger.account_id) : 1;
let conversation_id = trigger.conversation_id ? parseInt(trigger.conversation_id) : 0;

const reason = String(trigger.reason || trigger.motivo || '').trim();
const case_details = String(trigger.case_details || trigger.details || trigger.summary || trigger.informacion_caso || trigger.info || '').trim();
const query = (trigger.query || '').toString();

if (!conversation_id && query) {
  const m = query.match(/(?:conversation_id|conversacion|conversation|id)\s*[:=]?\s*(\d+)/i);
  if (m) conversation_id = parseInt(m[1]);
}

// Fallback: If conversation_id is still missing or 0, query recent open conversations from Chatwoot
if (!conversation_id) {
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url: `https://project1-chatwoot.efebpb.easypanel.host/api/v1/accounts/${account_id}/conversations?status=all`,
      headers: {
        'api_access_token': 'nuwRKpG2bBAQBpRFznfvrMpT',
        'Content-Type': 'application/json'
      },
      json: true
    });
    const convs = res.data?.payload || [];
    if (convs.length > 0) {
      conversation_id = convs[0].id;
    }
  } catch (e) {}
}

return [{
  json: {
    account_id: account_id || 1,
    conversation_id: conversation_id || 13,
    reason: reason,
    case_details: case_details,
    query: query
  }
}];

const convData = $('Obtener datos conversacion').first().json || {};
const triggerData = $('Preparar Datos Transferencia').first().json || {};

const conversation_id = triggerData.conversation_id || convData.id || 13;
const account_id = triggerData.account_id || convData.account_id || 1;
const sender = convData.meta?.sender || {};
const contact_name = sender.name || 'Cliente';
const contact_phone = sender.phone_number || (sender.identifier && /^\+?\d[\d\s-]{6,}$/.test(sender.identifier) ? sender.identifier : 'No registrado');
const contact_email = sender.email || 'No registrado';
const inbox_id = Number(convData.inbox_id || 0);

// Identificar marca según inbox
const isTVTotal24 = (inbox_id === 10 || inbox_id === 13 || inbox_id === 15 || inbox_id === 16 || inbox_id === 19);
const brandName = isTVTotal24 ? 'TVTotal24 (Latina)' : 'TotalTv USA';

// Motivo de la transferencia
let reason = String(triggerData.reason || '').trim();
if (!reason) {
  reason = 'Atención / Soporte requerido';
}

// Información recopilada del caso
let rawDetails = String(triggerData.case_details || '').trim();

// Fallback: Si no se pasó case_details por el tool, consultar los últimos mensajes entrantes del cliente en Chatwoot
if (!rawDetails) {
  try {
    const chatwootToken = 'nuwRKpG2bBAQBpRFznfvrMpT';
    const msgRes = await this.helpers.httpRequest({
      method: 'GET',
      url: `https://project1-chatwoot.efebpb.easypanel.host/api/v1/accounts/${account_id}/conversations/${conversation_id}/messages`,
      headers: { 'api_access_token': chatwootToken },
      json: true
    });
    const msgs = (msgRes.payload || []).filter(m => m.message_type === 0 || m.message_type === 'incoming');
    if (msgs.length > 0) {
      const recentIncoming = msgs.slice(-4).map(m => `• "${m.content}"`).join('\n');
      rawDetails = `Mensajes recientes del cliente:\n${recentIncoming}`;
    }
  } catch (e) {}
}

if (!rawDetails) {
  rawDetails = 'No se registraron detalles adicionales previo a la transferencia.';
}

// 1. Formato para Nota Privada en Chatwoot (Markdown)
const privateNote = `⚠️ **TRANSFERENCIA A SOPORTE HUMANO**

📌 **Motivo:** ${reason}
👤 **Contacto:** ${contact_name}
📱 **Teléfono:** ${contact_phone}
📧 **Email:** ${contact_email}
🏷️ **Canal / Inbox:** ${brandName} (Inbox #${inbox_id})
💬 **Conversación:** #${conversation_id}

📋 **INFORMACIÓN RECOPILADA DEL CASO:**
${rawDetails}`;

// Helper para escapar HTML en Telegram
const escapeHtml = (str) => String(str || '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

// 2. Formato para Telegram (HTML)
const telegramText = `🔔 <b>Transferencia a Soporte Humano</b>

👤 <b>Contacto:</b> ${escapeHtml(contact_name)}
📱 <b>Teléfono:</b> ${escapeHtml(contact_phone)}
📧 <b>Email:</b> ${escapeHtml(contact_email)}
🏷️ <b>Canal:</b> ${escapeHtml(brandName)} (Inbox #${inbox_id})
💬 <b>Conversación:</b> #${conversation_id}
📌 <b>Motivo:</b> ${escapeHtml(reason)}

📋 <b>Información Recopilada:</b>
${escapeHtml(rawDetails)}`;

// 3. Formato para WhatsApp Evolution API (WhatsApp Markdown)
const whatsappText = `🔔 *Transferencia a Soporte Humano*

👤 *Contacto:* ${contact_name}
📱 *Teléfono:* ${contact_phone}
📧 *Email:* ${contact_email}
🏷️ *Canal:* ${brandName} (Inbox #${inbox_id})
💬 *Conversación:* #${conversation_id}
📌 *Motivo:* ${reason}

📋 *Información Recopilada:*
${rawDetails}`;

// Preservar etiquetas y agregar 'human'
let currentLabels = Array.isArray(convData.labels) ? [...convData.labels] : [];
const alreadyHadHuman = currentLabels.includes('human');
if (!alreadyHadHuman) {
  currentLabels.push('human');
}

return [{
  json: {
    conversation_id,
    account_id,
    contact_name,
    contact_phone,
    contact_email,
    inbox_id,
    brand_name: brandName,
    reason,
    case_details: rawDetails,
    private_note_content: privateNote,
    telegram_text: telegramText,
    whatsapp_text: whatsappText,
    labels: currentLabels,
    already_had_human: alreadyHadHuman
  }
}];

const humanData = $('Agregar etiqueta human').first().json || {};
return [{
  json: {
    status: "success",
    human_transfer: "completed",
    conversation_id: humanData.conversation_id,
    contact_name: humanData.contact_name,
    reason: humanData.reason,
    message: "La conversación HA SIDO transferida exitosamente a un asesor humano en el sistema con la información recopilada.",
    instructions_for_ai: "REGLA OBLIGATORIA E INELUDIBLE: La transferencia a soporte humano ya se realizó con éxito en el sistema. En este mismo mensaje final al cliente DEBES confirmar obligatoria y explícitamente que su caso/conversación ha sido transferido a nuestro equipo de soporte humano y que un asesor lo atenderá a la brevedad dentro del horario extendido de oficina. ESTÁ TOTALMENTE PROHIBIDO decir que hubo un error o terminar tu respuesta sin confirmar esta transferencia."
  }
}];
